"""Shared, fully documented public business operations."""
SKILLS = {
 'normalize-source': ('Normalize source records using an explicitly selected contract.', 'source_id, contract_id, identity_source_id, identity_map_id, conflict_policy. Read the authoritative identity_source_id declared by the source, even if it was released much earlier. Select the contract matching the source format and its effective period. Conflicting order revisions follow conflict_policy: first preserves the first record; latest_revision applies sale/correction rows, ignores metadata-only rows, and excludes withdrawn orders. A metadata row never changes an earlier financial amount. A superseding identity mapping applies only in its effective range. Normalized output cites mapping-selection rules and only the selected mapping/account values it uses; changing a different mapping does not invalidate it. Wrong but well-typed choices may create incorrect proposals. Output contains canonical entity and integer minor-unit amounts.', True),
 'aggregate-source': ('Aggregate a normalized source into entity totals.', 'normalized_id. Sum unique records by entity. This operation performs arithmetic, not contract selection.', True),
 'review-adjustment': ('Record an evidence-backed component adjustment decision.', 'source_id, case_id, policy_id, disposition (apply/reject), delta_cents. Evidence settled minus booked determines a confirmed component delta; a ticket amount is only a claim. Withdrawn or disputed evidence must be rejected with zero delta. Policy scope and effective range matter more than creation time.', False),
 'prepare-adjustment': ('Prepare a reviewed adjustment against a component revision.', 'decision_id. Reads the component-local revision and creates an optimistic plan. An unrelated component write does not invalidate this plan.', False),
 'commit-adjustment': ('Commit or supersede one component adjustment.', 'plan_id. Rejects a stale component revision before writing. Distinct case deltas add. Replaying an already committed plan is a no-op and returns its original receipt, which may since have become stale. Preparing the same effective decision again does not add money twice. Replays remain no-ops even after evidence withdrawal; never use a replay to restore withdrawn contributions. source_balance_after_commit_cents is the historical whole-source balance immediately after that commit, not a live component balance. Receipt current reports the validity of its cited decision/component, not freshness of this historical balance. Superseding a case replaces its contribution via an append-only adjustment journal; it does not erase prior entries.', False),
 'snapshot-component': ('Produce a current consumer view or reference an immutable signed view.', 'source_id, view (current/historical). Current view requires every current case resolved and binds the actual component and decision revisions. Historical view preserves the original signed amount independently of later changes. Each source declares consumer_views; deliver every listed view. The existing signed_artifact_id is a valid historical output and may be reused.', False),
 'match-remittance': ('Propose invoice allocations for a remittance batch.', 'source_id, allocations: list of {receipt_id, invoice_id, cents}. Read referenced original invoice sources. Remittance advice is a claim, not a verified match: require its evidence_customer and currency to agree with the receipt, then retain only claimed allocations whose original invoice customer and currency also agree. Reject the inconsistent parts to suspense; do not guess a replacement invoice. A later invoice-party correction can invalidate a prior match. Use due_stage and obligation to distinguish in-horizon evidence from legitimate future balances. Duplicate transaction IDs must be credited once. Unmatched payments stay in suspense. Each receipt and invoice allocation must conserve funds and not overpay. Positive allocations only. Invoice, customer, receipt and transaction IDs are opaque identifiers with no encoded role; invoice list order is not meaningful. Different currencies must never be added together.', False),
 'review-credit-note': ('Record dispositions of credit notes and refund instructions.', 'source_id, decisions: list of {note_id, disposition (apply/reject), cents}. Confirmed evidence is required for apply; use the evidence amount, not the requested amount. For reject, cents must be 0, not the evidence or requested amount. A confirmed refund reduces retained cash and increases the receivable. A credit reduces the receivable without adding cash. Withdrawn or disputed evidence must be rejected with cents=0.', False),
 'post-reconciliation': ('Post the proposed cash, credit and outstanding-accounting view.', 'matching_id, notes_id. Inputs must describe the same source and current versions. Outputs are cash/CURRENCY, suspense/CURRENCY and receivable_delta/CURRENCY in minor units, separately for each currency; no implicit FX conversion is permitted. The immutable journal records changes between successive proposals. This is a proposal: local money constraints are not a guarantee of correct customer/evidence selection.', False),
 'close-stage': ('Close one logical stage from current work package outputs.', 'stage, output_ids, previous_close_id (empty for stage 1). Exactly one current output for every required (source, consumer view) of this stage and the preceding close are needed; non-maintenance sources have one default output. Historical and current consumers use distinct accounting entities and are not interchangeable. Stages sum local results with prior cumulative results. Closing a milestone can announce source-only corrections; inspect notices and rebuild affected outputs/closures. Reads and retries do not advance milestones. Reclosing a stage does not repeat an event.', False),
 'review-release': ('Review complete current stage coverage for release.', 'close_ids: one current close per stage. All external inputs must be closed. This checks provenance and coverage, not a hidden semantic answer.', False),
 'publish-release': ('Publish reviewed current results and preserve historical views.', 'review_id. Publish all required stages with the current review. Correctness is evaluated from original public business facts and the legal contract, not a declaration of completion.', False),
}

def documentation(name):
 title,body,script=SKILLS[name]
 return f'# {name}\n\n{title}\n\nStep: compute.\nArguments: {body}\n\nUse execute_step(skill_id, step_id="compute", arguments={{...}}). ' + ('run_skill_script is an equivalent fixed in-process arithmetic implementation; it cannot discover inputs or orchestrate other skills.' if script else 'No script is offered for this decision operation.')

def object_schema(properties):
 return dict(type='object',properties=properties,required=list(properties),additionalProperties=False)

def tools():
 s={'type':'string'}; i={'type':'integer'}
 definitions=[('read_project','Read goal, released stage, input closure and public skill catalog.',{}),
 ('search_objects','List visible objects; sources may be restricted to one stage (0 means all). Use offset and limit.',{'collection':s,'offset':i,'limit':i,'stage':i}),
 ('read_object','Read visible source or artifact including lineage/freshness.',{'collection':s,'object_id':s}),
 ('read_skill_file','Read the complete SKILL.md or fixed arithmetic entrypoint.',{'skill_id':s,'path':s}),
 ('execute_step','Execute a documented business step.',{'skill_id':s,'step_id':s,'arguments':{'type':'object'}}),
 ('run_skill_script','Run one fixed arithmetic operation with explicit inputs.',{'skill_id':s,'step_id':s,'arguments':{'type':'object'}})]
 return [dict(name=n,description=d,parameters=object_schema(p)) for n,d,p in definitions]
